// Package postgres implements ca.Store against PostgreSQL via
// jackc/pgx. The queries are generated by sqlc from queries.sql.
package postgres

import (
	"context"
	"time"

	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/internal/ca"
	"github.com/garamsh/garam/internal/ca/postgres/db"
	"github.com/garamsh/garam/internal/errorx"
	"github.com/garamsh/garam/internal/grn"
	"github.com/garamsh/garam/internal/pgxerr"
)

// Store implements ca.Store against PostgreSQL. What it writes for a
// private key is whatever ca.Sealer produced, never the key.
type Store struct {
	q *db.Queries
}

// Compile-time check that Store satisfies ca.Store.
var _ ca.Store = (*Store)(nil)

// New constructs a Postgres-backed ca.Store.
func New(pool *pgxpool.Pool) *Store {
	return &Store{q: db.New(pool)}
}

// Create persists a new Authority.
func (s *Store) Create(ctx context.Context, a *ca.Authority) error {
	err := s.q.CreateCertificateAuthority(ctx, db.CreateCertificateAuthorityParams{
		OrgGrn:      a.Organization.String(),
		Certificate: a.Certificate,
		SealedKey:   a.SealedKey,
		NotAfter:    stamp(a.NotAfter),
		CreatedAt:   stamp(a.CreatedAt),
	})
	return pgxerr.Classify(err, "create", nil, ca.ErrAuthorityAlreadyExists)
}

// Get returns the organization's Authority, or ca.ErrAuthorityNotFound.
func (s *Store) Get(ctx context.Context, orgGRN grn.GRN) (*ca.Authority, error) {
	row, err := s.q.GetCertificateAuthority(ctx, orgGRN.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "get", ca.ErrAuthorityNotFound, nil)
	}
	return rowToAuthority(row)
}

// rowToAuthority converts a sqlc row into the domain aggregate. A
// stored value that no longer parses is data corruption, hence
// internal.
func rowToAuthority(row db.CertificateAuthority) (*ca.Authority, error) {
	orgGRN, err := grn.Parse(row.OrgGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "org grn", errorx.KindInternal)
	}
	return &ca.Authority{
		Organization: orgGRN,
		Certificate:  row.Certificate,
		SealedKey:    row.SealedKey,
		NotAfter:     row.NotAfter.Time,
		CreatedAt:    row.CreatedAt.Time,
	}, nil
}

// stamp converts a time.Time to a valid pgtype.Timestamptz.
func stamp(t time.Time) pgtype.Timestamptz {
	return pgtype.Timestamptz{Time: t, Valid: true}
}
